            if len(items) < x["capacity"]:
                items.append(c["value"])
                out.append(None)
            else:
                out.append(False)
        elif c["op"] == "pop":
            if items:
                out.append(items.pop(0))
            else:
                out.append(None)
        else:
            if items:
                out.append(items[0])
            else:
                out.append(None)
    return out
